using System.Collections.Generic;
using FieldMedic.Interaction;
using UnityEngine;

namespace FieldMedic.Treatment
{
    /// <summary>
    /// Real IFAK models generated by the owner in Meshy AI (docs/MESHY_PROMPTS_V2.md). Editor/MeshyImporter turns
    /// SourceAssets/Meshy/&lt;file&gt;.glb|fbx into Resources/Meshy/&lt;file&gt;.prefab (real scale, longest axis = Z, thinnest = Y,
    /// centred, collider + grab point). At runtime <see cref="Apply"/> hides the procedural look of the carried state
    /// of an item and shows the Meshy model instead. No file -> the procedural model stays (fallback).
    /// Only the carried / packaged look is swapped; animated states (CAT band on a limb, open seal, unfolded blanket,
    /// bandage pad) stay procedural because the treatment logic drives their geometry.
    /// </summary>
    public static class MeshyModels
    {
        public const string ResourceFolder = "Meshy";

        public struct Entry
        {
            public string file;
            /// <summary>Child holding the carried look (null = the item's own "Merged_*" renderers).</summary>
            public string target;
            /// <summary>Longest dimension of the real object as carried, metres.</summary>
            public float length;
            /// <summary>Extra children to hide (moving parts drawn by the procedural model).</summary>
            public string[] extraHide;
            public Entry(string file, string target, float length, params string[] extraHide)
            { this.file = file; this.target = target; this.length = length; this.extraHide = extraHide; }
        }

        /// <summary>Fixed file names (must match docs/MESHY_PROMPTS_V2.md) and real sizes.</summary>
        public static readonly Dictionary<string, float> RealLength = new Dictionary<string, float>
        {
            { "cat_tourniquet", 0.17f }, { "israeli_bandage", 0.17f }, { "combat_gauze", 0.14f }, { "chest_seal", 0.20f },
            { "needle_decompression", 0.16f }, { "npa", 0.15f }, { "trauma_shears", 0.19f }, { "gloves", 0.15f },
            { "mylar_blanket", 0.13f }, { "sam_splint", 0.12f }, { "marker_card", 0.14f }, { "ifak_pouch", 0.21f },
            { "smoke_grenade", 0.15f }, { "marker", 0.14f }, { "casualty_card", 0.14f },
        };

        public static readonly Dictionary<MedItemKind, Entry> ByKind = new Dictionary<MedItemKind, Entry>
        {
            { MedItemKind.Tourniquet, new Entry("cat_tourniquet", "Folded", 0.17f) },
            { MedItemKind.IsraeliBandage, new Entry("israeli_bandage", null, 0.17f) },
            { MedItemKind.HemostaticGauze, new Entry("combat_gauze", null, 0.14f) },
            { MedItemKind.ChestSeal, new Entry("chest_seal", "Package", 0.20f) },
            { MedItemKind.DecompressionNeedle, new Entry("needle_decompression", null, 0.16f) },
            { MedItemKind.NasalAirway, new Entry("npa", null, 0.15f) },
            { MedItemKind.TraumaShears, new Entry("trauma_shears", null, 0.19f, "UpperBlade") },
            { MedItemKind.NitrileGloves, new Entry("gloves", null, 0.15f) },
            { MedItemKind.ThermalBlanket, new Entry("mylar_blanket", "Folded", 0.13f) },
            { MedItemKind.Marker, new Entry("marker", null, 0.14f) },
            { MedItemKind.CasualtyCard, new Entry("casualty_card", null, 0.14f) },
        };

        static readonly Dictionary<string, GameObject> Cache = new Dictionary<string, GameObject>();

        /// <summary>Optional override (tests): returns a prefab for a file name or null.</summary>
        public static System.Func<string, GameObject> Loader;

        public static GameObject Load(string file)
        {
            if (Loader != null) return Loader(file);
            if (Cache.TryGetValue(file, out var p)) return p;
            p = Resources.Load<GameObject>(ResourceFolder + "/" + file);
            Cache[file] = p;
            return p;
        }

        public static void ClearCache() => Cache.Clear();

        /// <summary>Swap the procedural carried look of `item` for the Meshy model. Returns the new visual or null.</summary>
        public static Transform Apply(MedItem item)
        {
            if (item == null || !ByKind.TryGetValue(item.kind, out var e)) return null;
            var prefab = Load(e.file);
            if (prefab == null) return null;
            return Apply(item.transform, prefab, e.target, item, false, e.extraHide);
        }

        /// <summary>IFAK pouch: the open tray layout (slots) stays, the Meshy pouch is fitted to its size.</summary>
        public static Transform ApplyPouch(Transform pouch)
        {
            var prefab = Load("ifak_pouch");
            return prefab == null ? null : Apply(pouch, prefab, "PouchVisual", null, true);
        }

        public static Transform Apply(Transform root, GameObject prefab, string target, Grabbable owner = null,
            bool fitToProcedural = false, string[] extraHide = null)
        {
            if (root == null || prefab == null) return null;
            Transform parent = root;
            var hide = new List<Renderer>();
            if (!string.IsNullOrEmpty(target))
            {
                var t = root.Find(target) ?? root.Find(MedItem.VisualName + "/" + target); // w9: carried look under "Visual"
                if (t == null) return null;
                parent = t;
                hide.AddRange(t.GetComponentsInChildren<Renderer>(true));
            }
            else
            {
                var holder = root.Find(MedItem.VisualName);
                foreach (Transform c in holder != null ? holder : root)
                {
                    if (!c.name.StartsWith("Merged_")) continue;
                    var r = c.GetComponent<Renderer>();
                    if (r != null) hide.Add(r);
                }
            }
            if (hide.Count == 0) return null;
            var extra = new List<Renderer>();
            if (extraHide != null)
                foreach (var n in extraHide)
                {
                    var t = root.Find(n);
                    if (t != null) extra.AddRange(t.GetComponentsInChildren<Renderer>(true));
                }

            // procedural bounds in parent space: the model is centred there
            var b = new Bounds();
            bool any = false;
            foreach (var r in hide)
            {
                var mf = r.GetComponent<MeshFilter>();
                if (mf == null || mf.sharedMesh == null) continue;
                var m = parent.worldToLocalMatrix * r.transform.localToWorldMatrix;
                var mb = mf.sharedMesh.bounds;
                for (int i = 0; i < 8; i++)
                {
                    var c = mb.center + Vector3.Scale(mb.extents, new Vector3((i & 1) == 0 ? -1 : 1, (i & 2) == 0 ? -1 : 1, (i & 4) == 0 ? -1 : 1));
                    var p = m.MultiplyPoint3x4(c);
                    if (!any) { b = new Bounds(p, Vector3.zero); any = true; } else b.Encapsulate(p);
                }
            }
            foreach (var r in hide) r.enabled = false;
            foreach (var r in extra) r.enabled = false;

            bool hadPoints = owner != null && owner.GetComponentsInChildren<GrabPoint>(true).Length > 0;
            var vis = Object.Instantiate(prefab, parent, false);
            vis.name = "MeshyVisual";
            vis.transform.localPosition = any ? b.center : Vector3.zero;
            vis.transform.localRotation = Quaternion.identity;
            if (fitToProcedural && any)
            {
                var vb = new Bounds();
                bool v = false;
                foreach (var r in vis.GetComponentsInChildren<Renderer>(true))
                    if (!v) { vb = r.bounds; v = true; } else vb.Encapsulate(r.bounds);
                float want = Mathf.Max(b.size.x, b.size.z), have = v ? Mathf.Max(vb.size.x, vb.size.z) : 0f;
                // renderer bounds are in world space, the procedural bounds in parent space
                if (have > 1e-4f) vis.transform.localScale *= want * Mathf.Abs(parent.lossyScale.x) / have;
            }
            // the item keeps its own fitted collider; points only where the item had none (do not change tuned grabs)
            foreach (var c in vis.GetComponentsInChildren<Collider>(true)) Object.DestroyImmediate(c);
            if (hadPoints || owner == null) foreach (var g in vis.GetComponentsInChildren<GrabPoint>(true)) Object.DestroyImmediate(g.gameObject);
            foreach (var r in vis.GetComponentsInChildren<Renderer>(true)) r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            if (owner != null) owner.RefreshGrabPoints();
            return vis.transform;
        }
    }
}
